<?php
/** Real native behavior, confined to a task-owned disposable database. */
if(PHP_SAPI!=='cli'||!defined('KIWE_FEEDBACK_OWNED_DATABASE')||DB_NAME!==KIWE_FEEDBACK_OWNED_DATABASE||!preg_match('/^kiwe_fb_20261029_(store|editorial)$/D',DB_NAME))throw new RuntimeException('Owned Feedback fixture required.');

function kiwe_feedback_app_tests(bool $store): array {
	global $wpdb;
	$checks=[];$GLOBALS['feedbackChecks']=&$checks;
	$check=static function($ok,string $label)use(&$checks){$checks[$label]=(bool)$ok;if(!$ok)throw new RuntimeException($label);};
	$error=static fn($v)=>is_wp_error($v)?$v->get_error_code():'';
	wp_set_current_user(1);
	DSA\Discussion\Site_Conversation::register();
	add_filter('comments_open',[DSA\Discussion\Site_Conversation::class,'filter_open'],20,2);
	$check(DSA\Discussion\Feedback_Access::enabled(),'Feedback is built into Core');
	$check(count(DSA\Apps\Runtime_Contract::IDS)===5&&!in_array('feedback',DSA\Apps\Runtime_Contract::IDS,true),'The native Apps library contains only the five optional Apps');
	$app_workspace=new DSA\Access\App_Workspace_Service();
	$check($app_workspace->snapshot()['canFeedback']&&str_contains(DSA\Access\App_Workspace_Service::url('settings','feedback'),'app_tab=feedback'),'The authorized App settings projection exposes its Feedback tab');
	$original=get_option('default_comment_status');
	$count=(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$wpdb->posts} WHERE post_type=%s",DSA\Discussion\Site_Conversation::TYPE));
	$policy=DSA\Discussion\Discussion_Settings::read();
	$check(isset($policy['values']['siteWide'])&&!isset($policy['values']['sitePage'],$policy['pages']),'Settings expose one boolean and no public-page chooser');
	$check(false===$policy['values']['siteWide']&&DSA\Discussion\Discussion_Target::automatic_id(0)===0,'New sites have no implicit conversation until explicitly enabled');
	DSA\Discussion\Discussion_Contract::export();DSA\Discussion\Discussion_Settings::read();
	$check($count===(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$wpdb->posts} WHERE post_type=%s",DSA\Discussion\Site_Conversation::TYPE)),'Public discovery and settings reads create no native records');
	$enabled=DSA\Discussion\Discussion_Settings::save(['field'=>'siteWide','value'=>true,'expected'=>$policy['expected']]);
	$check(!is_wp_error($enabled)&&true===$enabled['values']['siteWide'],'Explicit enable creates the conversation through native WordPress');
	$site=DSA\Discussion\Site_Conversation::id();$thread=get_post($site);
	$check($site>0&&DSA\Discussion\Site_Conversation::owns($thread)&&$thread->post_type===DSA\Discussion\Site_Conversation::TYPE,'One native internal object owns site-wide comments');
	$type=get_post_type_object($thread->post_type);
	$check(!$type->public&&!$type->publicly_queryable&&!$type->show_ui&&!$type->show_in_rest,'The conversation does not create a public page or editor collection');
	$page=wp_insert_post(['post_type'=>'page','post_status'=>'publish','post_title'=>'Fixture contact','comment_status'=>'closed'],true);
	$article=wp_insert_post(['post_type'=>'post','post_status'=>'publish','post_title'=>'Fixture article','comment_status'=>'open'],true);
	$private=wp_insert_post(['post_type'=>'post','post_status'=>'private','post_title'=>'Private fixture'],true);
	$check(DSA\Discussion\Discussion_Target::automatic_id(0)===$site&&DSA\Discussion\Discussion_Target::automatic_id((int)$page)===$site,'Home, archives and ordinary pages share exactly one target');
	$check(DSA\Discussion\Discussion_Target::automatic_id((int)$article)===(int)$article,'A post keeps its own conversation');
	$check(is_wp_error(DSA\Discussion\Discussion_Target::get((int)$private)),'Internal conversation support does not expose private posts');
	$descriptor=DSA\Discussion\Discussion_Target::descriptor($thread);
	$check($descriptor['kind']==='site'&&$descriptor['open']&&str_starts_with($descriptor['url'],home_url('/')),'Site conversation has a readable website label and native shell link');
	$repeat=DSA\Discussion\Discussion_Settings::save(['field'=>'siteWide','value'=>true,'expected'=>$enabled['expected']]);
	$check(!is_wp_error($repeat)&&DSA\Discussion\Site_Conversation::id()===$site,'Repeated enable reuses the existing record');
	$comment=wp_insert_comment(['comment_post_ID'=>$site,'comment_content'=>'A synthetic website experience.','comment_author'=>'Fixture Reader','comment_author_email'=>'fixture@example.test','comment_approved'=>1,'comment_type'=>'comment']);
	$check($comment>0&&DSA\Onboarding\Context_Selection_Service::public_testimonial(get_comment($comment)),'Approved website feedback remains eligible for native testimonial curation');
	$feedback=(new DSA\Access\Comment_Moderation_Service())->listing(['type'=>'website']);
	$match=array_values(array_filter($feedback['items']??[],static fn($v)=>$v['id']===$comment));
	$check(count($match)===1&&$match[0]['context']==='website'&&!isset($feedback['policy']),'Daily shows website activity without returning configuration');
	$off=DSA\Discussion\Discussion_Settings::save(['field'=>'siteWide','value'=>false,'expected'=>$repeat['expected']]);
	$check(!is_wp_error($off)&&!comments_open($site)&&DSA\Discussion\Discussion_Target::automatic_id(0)===0,'Switching site-wide feedback off closes new submissions everywhere outside posts/products');
	$check(get_comment($comment)&&!is_wp_error(DSA\Discussion\Discussion_Target::get($site))&&DSA\Onboarding\Context_Selection_Service::public_testimonial(get_comment($comment)),'Off preserves approved history and curated testimonial eligibility');
	$stale=DSA\Discussion\Discussion_Settings::save(['field'=>'siteWide','value'=>true,'expected'=>$repeat['expected']]);
	$check('kiwe_discussion_policy_stale'===$error($stale),'An outdated settings form cannot overwrite newer policy');
	$invalid=DSA\Discussion\Discussion_Settings::save(['field'=>'sitePage','value'=>(int)$page,'expected'=>$off['expected']]);
	$check('kiwe_discussion_policy_input'===$error($invalid),'Removed page-selection payloads cannot mutate policy');
	$check(get_option('default_comment_status')===$original,'Site-wide changes preserve the native new-post default');
	$subscriber=wp_create_user('feedback_reader',wp_generate_password(30),'feedback-only-reader@example.test');
	$check(!is_wp_error($subscriber),'The denied actor is a separately created native subscriber');
	(new WP_User($subscriber))->set_role('subscriber');
	wp_set_current_user($subscriber);
	$check(DSA\Discussion\Discussion_Settings::read()===[]&&'kiwe_discussion_policy_denied'===$error(DSA\Discussion\Discussion_Settings::save(['field'=>'siteWide','value'=>true,'expected'=>$off['expected']])),'A subscriber cannot read or change website settings');
	wp_set_current_user(1);
	$post_service=new DSA\Access\Post_Workspace_Service();$post_record=$post_service->post((int)$article);
	$check(!is_wp_error($post_record)&&$post_record['commentsAllowed']&&$post_record['feedbackAvailable'],'Kiwe post editor exposes its existing native comment setting');
	$post_input=['title'=>$post_record['title'],'content'=>$post_record['content'],'status'=>$post_record['status'],'categories'=>$post_record['categories'],'tags'=>$post_record['tags'],'seo'=>$post_record['seo'],'expected'=>$post_record['expected'],'commentsAllowed'=>false];
	$post_saved=$post_service->save((int)$article,$post_input);
	$check(!is_wp_error($post_saved)&&$post_saved['commentsAllowed']===false&&!comments_open($article),'The post control saves the native discussion flag');
	$check($post_saved['title']===$post_record['title']&&$post_saved['content']===$post_record['content']&&$post_saved['tags']===$post_record['tags'],'Changing post comment availability preserves the original writing and tags');
	$check('kiwe_post_stale'===$error($post_service->save((int)$article,$post_input)),'An old post form cannot overwrite a changed comment setting');
	$_SERVER['HTTP_ORIGIN']=home_url();
	$workspace=new DSA\Access\Feedback_Workspace_Service();
	$request=new WP_REST_Request('POST','/dsa/v1/workspace/feedback');$request->set_header('Content-Type','application/json');$request->set_header('X-WP-Nonce',wp_create_nonce('wp_rest'));$request->set_header('X-Kiwe-Mutation','1');$request->set_body(wp_json_encode(['operation'=>'discussion','field'=>'accountRequired','value'=>true,'expected'=>$off['expected']]));
	$check($workspace->permission($request)&&$workspace->save($request)->get_status()===400,'The actual Daily API refuses settings operations even for an owner');
	$request->set_header('X-WP-Nonce','not-a-current-nonce');
	$check(!$workspace->permission($request),'The Feedback App rejects a missing or invalid actor nonce');
	if($store){
		update_option('woocommerce_enable_reviews','yes');
		add_post_type_support('product','comments');
		$product=new WC_Product_Simple();$product->set_name('Feedback product fixture');$product->set_status('publish');$product->set_regular_price('42');$product->set_reviews_allowed(false);$id=$product->save();
		$check(!DSA\Discussion\Discussion_Target::descriptor(get_post($id))['open'],'A closed product stays closed despite global reviews being enabled');
		$service=new DSA\Access\Commerce_App_Service();$list=$service->workspace('products',1,$id);$record=$list['products'][0]??null;
		$check($record&&$record['id']===$id&&$record['reviewsAllowed']===false&&$record['feedbackAvailable'],'Kiwe product editor exposes the native per-product review flag');
		$input=['expected'=>$record['expected'],'name'=>$record['name'],'status'=>$record['status'],'price'=>$record['price'],'categories'=>$record['categories'],'reviewsAllowed'=>true];
		$saved=$service->save_product_record($id,$input);
		if(is_wp_error($saved))throw new RuntimeException('Native product review save refused: '.$saved->get_error_code().' / '.$saved->get_error_message());
		$check($saved['reviewsAllowed']&&wc_get_product($id)->get_reviews_allowed(),'The product control saves the native WooCommerce review flag');
		$check(comments_open($id),'The saved product accepts new reviews when native product discussions are enabled');
		$check($saved['price']===$record['price']&&$saved['description']===$record['description']&&$saved['stock']===$record['stock'],'Changing review availability preserves price, writing and inventory');
		$check('kiwe_commerce_stale'===$error($service->save_product_record($id,$input)),'An old product form cannot overwrite a changed review setting');
		$review_policy=DSA\Commerce\Discussion_Review_Adapter::policy();
		$check(!is_wp_error($review_policy)&&$review_policy['values']['enabled'],'Feedback settings reuse the original WooCommerce review policy');
		$check(DSA\Discussion\Discussion_Target::automatic_id($id)===$id,'A product keeps its review conversation rather than website feedback');
	}else{
		$check(!function_exists('WC')&&!DSA\Apps\Store_App_Service::enabled(),'The non-store profile runs without WooCommerce');
		$contract=DSA\Discussion\Discussion_Contract::export();$check($contract['productReviews']===false,'Non-store authoring discovery omits product reviews');
	}
	update_option('kiwe_feedback_app_enabled_v1','0',false);
	$check(DSA\Discussion\Feedback_Access::enabled(),'A retired optional-App flag cannot disable built-in Feedback');
	$check(DSA\Discussion\Discussion_Contract::export()['available']===true&&get_comment($comment),'Built-in discovery and native feedback remain available');
	$check(DSA\Discussion\Discussion_Contract::export()['settingsOwner']==='app-settings-feedback','Authoring discovery identifies the App settings Feedback tab');
	$check(DSA\Discussion\Discussion_Privacy::exporters([])!==[]&&DSA\Discussion\Discussion_Privacy::erasers([])!==[],'Built-in Feedback retains native privacy export and erasure');
	delete_option('kiwe_feedback_app_enabled_v1');
	return ['passed'=>true,'store'=>$store,'checks'=>$checks,'externalDelivery'=>false];
}
